import { targetciSearch } from "@/api/system/ciModel";
export default {
  name: '',
  components: {
    // TsFormSelect
  },
  props: {
    attrData: {
      type: Object
    },
    valueList: {
      type: Array
    }
  },
  data: function data() {
    var _this = this;
    return {
      options: [],
      currentValue: '',
      multiple: false,
      validateList: [],
      searchConfig: {
        multiple: true,
        border: 'border',
        search: true,
        width: '100%',
        dynamicUrl: '/api/rest/cmdb/attr/targetci/search?attrId=' + this.attrData.id,
        textName: 'name',
        valueName: 'id',
        transfer: true,
        onChange: function onChange(val, opt) {
          if (opt) {
            if (Array.isArray(opt)) {
              _this.$emit('setData', val, opt.filter(function (d) {
                return d.text;
              }));
            } else {
              _this.$emit('setData', val, opt.text);
            }
          } else {
            _this.$emit('setData', '', '');
          }
        }
      }
    };
  },
  beforeCreate: function beforeCreate() {},
  created: function created() {},
  beforeMount: function beforeMount() {},
  mounted: function mounted() {
    // this.getData()
  },
  beforeUpdate: function beforeUpdate() {},
  updated: function updated() {},
  activated: function activated() {},
  deactivated: function deactivated() {},
  beforeDestroy: function beforeDestroy() {},
  destroyed: function destroyed() {},
  methods: {
    setData: function setData(val) {
      this.$emit('setData', [val]);
    },
    getData: function getData() {
      var _this2 = this;
      var params = {
        attrId: this.attrData.id,
        currentPage: 1,
        keyword: "",
        pageSize: 20
      };
      targetciSearch(params).then(function (res) {
        // console.log(8801, res)
        _this2.options = res.Return;
      });
      if (this.valueList && this.valueList.length > 0) {
        this.currentValue = this.valueList[0];
      } else {
        this.currentValue = '';
      }
    }
  },
  filter: {},
  computed: {},
  watch: {
    valueList: {
      handler: function handler(newValue, oldValue) {
        this.getData();
      },
      deep: true,
      immediate: true
    }
  }
};
